function resolveEnumValue<T extends string>(enumObject: Record<string, T>, ...terms: string[]): T {
  const values = Object.values(enumObject);
  const normalized = values.map((value) => ({
    value,
    key: String(value).toUpperCase().replace(/[^A-Z0-9]/g, ""),
  }));

  const found = normalized.find(({ key }) =>
    terms.some((term) => key.includes(term.toUpperCase().replace(/[^A-Z0-9]/g, "")))
  );

  return found?.value ?? values[0];
}

function getDifficulty(categoryName: string, questionIndex: number): Difficulty {
  // 200 questions/category, moving from beginner to expert in 20-question blocks.
  if (questionIndex < 40) return resolveEnumValue(Difficulty, "EASY", "BEGINNER");
  if (questionIndex < 120) return resolveEnumValue(Difficulty, "MEDIUM", "INTERMEDIATE");
  return resolveEnumValue(Difficulty, "HARD", "ADVANCED", "EXPERT");
}

function getInterviewType(categoryName: string): InterviewType {
  const name = categoryName.toLowerCase();

  if (name.includes("qa")) {
    return resolveEnumValue(InterviewType, "QA", "TECHNICAL", "GENERAL");
  }
  if (name.includes("sales")) {
    return resolveEnumValue(InterviewType, "SALES", "BEHAVIORAL", "GENERAL");
  }
  return resolveEnumValue(InterviewType, "TECHNICAL", "CODING", "GENERAL");
}

function getExperienceLevel(categoryName: string, questionIndex: number): ExperienceLevel {
  const values = Object.values(ExperienceLevel) as ExperienceLevel[];
  const normalized = values.map((value) => ({
    value,
    key: String(value).toUpperCase().replace(/[^A-Z0-9]/g, ""),
  }));

  const find = (...terms: string[]) =>
    normalized.find(({ key }) => terms.some((term) => key.includes(term)))?.value;

  const category = categoryName.toLowerCase();

  if (category.includes("fresher") || category.includes("internship")) {
    return find("FRESHER", "ENTRY", "INTERN", "JUNIOR") ?? values[0];
  }

  if (category.includes("1-2")) {
    return questionIndex < 40
      ? (find("FRESHER", "ENTRY", "JUNIOR") ?? values[0])
      : (find("MID", "INTERMEDIATE", "JUNIOR") ?? values[0]);
  }

  if (category.includes("2-4")) {
    return questionIndex < 40
      ? (find("MID", "INTERMEDIATE", "JUNIOR") ?? values[0])
      : (find("EXPERIENCED", "SENIOR", "MID") ?? values[0]);
  }

  if (category.includes("senior") || category.includes("5+") || category.includes("10+")) {
    return find("SENIOR", "EXPERIENCED", "LEAD") ?? values[values.length - 1];
  }

  return questionIndex < 80
    ? (find("MID", "INTERMEDIATE", "JUNIOR") ?? values[0])
    : (find("EXPERIENCED", "SENIOR", "MID") ?? values[0]);
}

function getCategoryGroup(categoryName: string): string {
  if (categoryName === "HTML-CSS") return "Web Development";
  if (categoryName === "DevOps") return "DevOps";
  if (categoryName === "GenerativeAI") return "Artificial Intelligence";
  if (categoryName === "DataScience") return "Data Science";
  if (categoryName === "API-WebService") return "Backend Development";
  if (categoryName === "ComputerScience") return "Computer Science";
  if (categoryName === "DataStructureAndAlgorithms") return "Computer Science";
  if (categoryName === "CyberSeqcurity") return "Cyber Security";
  if (categoryName === "Kafka") return "Backend Development";
  if (categoryName === "SystemArchitecture") return "Architecture";
  if (categoryName === "Sales") return "Sales";
  if (categoryName.startsWith("Software engineer")) return "Software Engineering";
  if (categoryName.startsWith("Senior Software engineer")) return "Software Engineering";
  if (categoryName.startsWith("Software Architecture")) return "Software Architecture";
  if (categoryName === "Backend Engineer") return "Software Engineering";
  if (categoryName === "Frontend Engineer") return "Software Engineering";
  if (categoryName.startsWith("QA")) return "Quality Assurance";
  return "Interview Preparation";
}


function buildExplanation(categoryName: string, question: string): string {
  return `${question} is a core ${categoryName} interview concept. A strong answer should define the concept clearly, explain how it works, show where it is useful, and discuss practical trade-offs. The candidate should connect the explanation to a realistic engineering or business scenario and distinguish the concept from closely related alternatives.`;
}

function buildKeyPoints(categoryName: string, question: string): string[] {
  return [
    `Core definition of the concept`,
    `How it works in ${categoryName}`,
    `Practical use case or example`,
    `Benefits and limitations`,
    `Important trade-offs and alternatives`,
  ];
}

function buildCommonMistakes(categoryName: string, question: string): string[] {
  return [
    `Giving only a memorized definition without explaining practical usage`,
    `Ignoring important limitations or trade-offs`,
    `Confusing the concept with a related ${categoryName} concept`,
    `Using an example that does not match the stated requirement`,
    `Failing to discuss how the approach would be validated in practice`,
  ];
}

function buildFollowUps(categoryName: string, question: string): string[] {
  const categoryQuestions = questions.filter((item) => item[0] === categoryName);
  const currentIndex = categoryQuestions.findIndex((item) => item[1] === question);

  if (currentIndex === -1 || categoryQuestions.length <= 1) {
    return [];
  }

  const followUps: string[] = [];

  for (let offset = 1; offset <= categoryQuestions.length && followUps.length < 5; offset += 1) {
    const candidate = categoryQuestions[(currentIndex + offset) % categoryQuestions.length][1];

    if (candidate !== question && !followUps.includes(candidate)) {
      followUps.push(candidate);
    }
  }

  return followUps;
}

function buildTags(categoryName: string, question: string): string[] {
  const words = question
    .replace(/[^a-zA-Z0-9\s-]/g, " ")
    .split(/\s+/)
    .filter((word) => word.length > 2)
    .slice(0, 6);

  return Array.from(new Set([
    categoryName.toLowerCase(),
    ...words.map((word) => word.toLowerCase()),
    "interview",
  ]));
}

async function main() {
  let questionIndexByCategory: Record<string, number> = {};

  for (const [categoryName, question, slug, shortDescription, sampleAnswer] of questions) {
    const questionIndex = questionIndexByCategory[categoryName] ?? 0;
    questionIndexByCategory[categoryName] = questionIndex + 1;

    const experienceLevel = getExperienceLevel(categoryName, questionIndex);
    const difficulty = getDifficulty(categoryName, questionIndex);
    const interviewType = getInterviewType(categoryName);

    const category = await prisma.category.upsert({
      where: { slug: categoryName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") },
      update: { name: categoryName, group: getCategoryGroup(categoryName) },
      create: {
        name: categoryName,
        slug: categoryName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""),
        group: getCategoryGroup(categoryName),
      },
    });
    await prisma.interviewQuestion.upsert({
      where: { slug },
      update: {
        categoryId: category.id,
        question,
        shortDescription,
        sampleAnswer,
        isPublished: true,
        experienceLevel,
        difficulty,
        interviewType,
        explanation: buildExplanation(categoryName, question),
        keyPoints: buildKeyPoints(categoryName, question),
        commonMistakes: buildCommonMistakes(categoryName, question),
        followUpQuestions: buildFollowUps(categoryName, question),
        tags: buildTags(categoryName, question),
      },
      create: {
        categoryId: category.id,
        question,
        slug,
        shortDescription,
        sampleAnswer,
        isPublished: true,
        experienceLevel,
        difficulty,
        interviewType,
        explanation: buildExplanation(categoryName, question),
        keyPoints: buildKeyPoints(categoryName, question),
        commonMistakes: buildCommonMistakes(categoryName, question),
        followUpQuestions: buildFollowUps(categoryName, question),
        tags: buildTags(categoryName, question),
      },
    });
  }
  console.log("SUCCESS: Seeded 4400 interview questions (22 categories x 200).");
}

main().catch((error) => { console.error(error); process.exit(1); }).finally(async () => { await prisma.$disconnect(); });
